interface IState { void Publish(Document doc); }

sealed class Draft : IState {
    public static readonly Draft Instance = new();
    public void Publish(Document doc) => doc.State = Moderation.Instance;
}

sealed class Document {
    public IState State { get; set; } = Draft.Instance;
    public void Publish() => State.Publish(this);
}

